t.script:
// 
    document.addEventListener('DOMContentLoaded', function() {
        const searchInput = document.getElementById('product-search-input');
        const sortSelect = document.getElementById('product-sort-select');
        const priceMinInput = document.getElementById('price-min-input');
        const priceMaxInput = document.getElementById('price-max-input');
        const productsContainer = document.getElementById('products-container');
        let searchTimeout;

        // Handle search input
        if (searchInput) {
            searchInput.addEventListener('input', function(e) {
                const searchQuery = e.target.value;

                // Clear previous timeout
                clearTimeout(searchTimeout);

                // Debounce search by 300ms
                searchTimeout = setTimeout(function() {
                    fetchProducts();
                }, 300);
            });
        }

        // Handle sort change
        if (sortSelect) {
            sortSelect.addEventListener('change', function(e) {
                fetchProducts();
            });
        }

        // Handle price range inputs
        if (priceMinInput) {
            priceMinInput.addEventListener('input', function(e) {
                clearTimeout(searchTimeout);
                searchTimeout = setTimeout(function() {
                    fetchProducts();
                }, 500);
            });
        }

        if (priceMaxInput) {
            priceMaxInput.addEventListener('input', function(e) {
                clearTimeout(searchTimeout);
                searchTimeout = setTimeout(function() {
                    fetchProducts();
                }, 500);
            });
        }

        function fetchProducts() {
            const searchQuery = searchInput ? searchInput.value : '';
            const sortBy = sortSelect ? sortSelect.value : '';
            const priceMin = priceMinInput ? priceMinInput.value : '';
            const priceMax = priceMaxInput ? priceMaxInput.value : '';

            // Make AJAX call to search endpoint
            fetch('/shop/search', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        search_query: searchQuery,
                        sort_by: sortBy,
                        price_min: priceMin,
                        price_max: priceMax
                    }
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result) {
                    updateProductsGrid(data.result);
                }
            })
            .catch(error => {
                console.error('Search/Sort error:', error);
            });
        }

        function updateProductsGrid(products) {
            if (!productsContainer) return;

            if (products.length === 0) {
                productsContainer.innerHTML = '<div class="col-12"><p>No products found.</p></div>';
                return;
            }

            let html = '';
            products.forEach(function(product) {
                html += `
                    <div class="col-lg-4 col-md-6 mb-4">
                        <div class="card h-100" style="border: 1px solid #e5e5e5; border-radius: 12px; overflow: hidden; position: relative;">
                            <div style="position: absolute; top: 10px; left: 10px; z-index: 2;">
                                <span class="badge" style="background: #ff4444; color: white; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; font-weight: 600; display: block; margin-bottom: 5px;">Best Seller</span>
                                <span class="badge" style="background: #ff4444; color: white; padding: 6px 12px; border-radius: 6px; font-size: 0.75rem; font-weight: 600;">-27%</span>
                            </div>
                            <div style="position: absolute; top: 10px; right: 10px; z-index: 2;">
                                <button class="btn btn-light" style="width: 35px; height: 35px; border-radius: 50%; padding: 0;"><i class="fa fa-heart-o"></i></button>
                            </div>
                            <div style="background: #f5f5f5; padding: 20px; text-align: center; height: 250px; display: flex; align-items: center; justify-content: center; overflow: hidden;">
                                <img src="${product.image_url}" alt="Product" style="max-width: 100%; max-height: 100%; object-fit: cover;"/>
                            </div>
                            <div style="position: absolute; bottom: 180px; right: 10px; z-index: 2;">
                                <a href="/shop_details/{{product.id}}" class="btn btn-light" style="width: 35px; height: 35px; border-radius: 50%; padding: 0;"><i class="fa fa-eye"></i></a>
                            </div>
                            <div class="card-body">
                                <h6 class="card-title" style="font-weight: 700; font-size: 0.95rem; margin-bottom: 8px;">${product.name}</h6>
                                <div class="d-flex align-items-center mb-3">
                                    <span style="font-weight: 700; font-size: 1.25rem; color: #000;">${product.currency_symbol} ${product.list_price.toFixed(2)}</span>
                                </div>
                                <form action="/shop/cart/add" method="POST" class="add-to-cart-form">
                                    <input type="hidden" name="csrf_token" value="${document.querySelector('input[name=csrf_token]').value}" />
                                    <input type="hidden" name="product_id" value="${product.id}" />
                                    <button type="submit" class="btn w-100" style="background: #1a1a1a; color: white; border: none; border-radius: 8px; padding: 12px; font-weight: 600;">Add to Cart</button>
                                </form>
                            </div>
                        </div>
                    </div>
                `;
            });

            productsContainer.innerHTML = html;

            // Update product count
            const productCountEl = document.getElementById('product-count');
            if (productCountEl) {
                productCountEl.textContent = 'Showing ' + products.length + ' products';
            }
        }
    });
//
